  "appBarTitle": "Vet Policy",
  "screenTitle": "Application Policies\n",
  "sectionDataUsageTitle": "Data Usage",
  "sectionDataUsagePoints.0": "The company has the right to access and manage users' personal data in accordance with data protection regulations in Saudi Arabia.",
  "sectionDataUsagePoints.1": "The company has the right to modify or update user information according to the app’s policies, respecting privacy and compliance with laws.",
  "sectionUserResponsibilitiesTitle": "User Responsibilities",
  "sectionUserResponsibilitiesPoints.0": "The client is obligated to use the application only for authorized purposes and is prohibited from using it for illegal activities or providing misleading information.",
  "sectionUserResponsibilitiesPoints.1": "The client is responsible for the accuracy of the information provided through the app, such as animal data or medical history.",
  "sectionUserResponsibilitiesPoints.2": "The client acknowledges that United Feed Company is not responsible for any errors resulting from incorrect information submitted by the client.",
  "sectionUserResponsibilitiesPoints.3": "The client is required to pay service fees according to the prices listed within the app.",
  "sectionUserResponsibilitiesPoints.4": "All paid fees are non-refundable, except in cases decided by the company.",
  "sectionUserResponsibilitiesPoints.5": "The client must treat veterinarians with respect and not misuse the service.",
  "sectionUserResponsibilitiesPoints.6": "The client is not entitled to demand prescriptions or treatments beyond the scope of consultation provided through the app.",
  "sectionUserResponsibilitiesPoints.7": "The client acknowledges that the company provides no guarantees regarding the accuracy or effectiveness of veterinary consultations.",
  "sectionUserResponsibilitiesPoints.8": "By using the app, the client agrees to all these terms.",
  "sectionDisclaimerTitle": "Disclaimer",
  "sectionDisclaimerPoints.0": "The company is not responsible for any damages resulting from app usage, including technical failures or misuse of information.",
  "sectionDisclaimerPoints.1": "The client agrees that any decisions related to animal health are at their own responsibility, and United Feed Company is not liable for any results following veterinary recommendations.",
  "sectionDisclaimerPoints.2": "The company is not responsible for any errors or inaccurate information provided by veterinarians through the app.",
  "sectionDisclaimerPoints.3": "The company is not obligated to provide medications or treatments based on veterinary recommendations through the app.",
  "sectionDisclaimerPoints.4": "Any extra requests outside the scope of the app, such as direct contact with the veterinarian off-platform, are entirely at the client’s responsibility.",
  "sectionDisclaimerPoints.5": "The app is used at the user’s own personal responsibility.",
  "sectionThirdPartyTitle": "If Veterinarians Are Third-Party",
  "sectionThirdPartyPoints.0": "The company bears no responsibility for professional actions performed by veterinarians, who act as independent service providers, not employees of the company.",
  "sectionThirdPartyPoints.1": "Any consultations or treatments offered by the veterinarian are their personal responsibility, and users should refer to them in case of issues.",
  "sectionThirdPartyPoints.2": "The company's role is limited to providing a tech platform to connect clients with veterinarians, and it does not interfere in medical decisions or treatment recommendations.",
  "sectionThirdPartyPoints.3": "The company provides a platform for clients and veterinarians, but does not guarantee the accuracy or effectiveness of any veterinary consultation provided via the app.",
  "sectionEmployeeTitle": "If Veterinarians Are Employees",
  "sectionEmployeePoints.0": "Veterinary services through the app are provided by qualified and certified veterinarians.",
  "sectionEmployeePoints.1": "Any medical or treatment decisions made by the client based on consultations are their responsibility, and the company assumes no liability for outcomes.",
  "sectionEmployeePoints.2": "Veterinary consultations through the app depend on information provided by the client, so diagnosis accuracy depends on the quality of that information.",
  "sectionEmployeePoints.3": "In the case of medical errors or misinterpretations, the company holds no legal or financial liability for any harm to animals or clients.",
  "sectionTreatmentDisclaimerTitle": "Treatment and Medical Service Disclaimer",
  "sectionTreatmentDisclaimerPoints.0": "The company is not obligated to provide treatments; clients must obtain medications externally.",
  "sectionTreatmentDisclaimerPoints.1": "Service fees cover only the veterinary consultation through the app and do not include medications or field visits.",
  "sectionTreatmentDisclaimerPoints.2": "The company is not required to provide medications or treatments based on veterinary recommendations through the app.",
  "sectionTreatmentDisclaimerPoints.3": "Consultations provided through the app are for general guidance and do not replace clinical examinations at veterinary clinics.",
  "sectionTreatmentDisclaimerPoints.4": "The company has the right to modify or terminate veterinary consultation services at any time per its internal policies.",
